.container-botao {
    display: flex;
    align-items: center;
    justify-content: center;
    width: fit-content;
    border-radius: 100px;
    z-index: 1;
    padding: 3px;
    background: linear-gradient(to right, rgba(255, 255, 255, var(--dg1, 0)) 0%, transparent 40%, transparent 60%, rgba(255, 255, 255, var(--dg2, 0.2)));
}

.botao {
    border-radius: 100px;
    z-index: 3;
    position: relative;
    overflow: hidden;
}

.botao .elementor-button {
    background: #00FE00 !important; /* Botão verde */
    border: 2px solid #ffffff;
    padding: 0.5rem 4rem;
    border-radius: 100px;
    transition: 0.3s;
}

.botao .elementor-button::before {
    content: "";
    position: absolute;
    top: 50%;
    left: 50%;
    width: 204px;
    height: 103px;
    background-image: radial-gradient(
        43.3% 44.23% at 50% 49.51%,
        #EAFFEA 10%,   /* tom verde bem claro */
        #B6FFB6 10%, /* verde mais suave */
        #8FF58F 40%,/* verde médio */
        #F0FFF000 100% /* branco esverdeado totalmente transparente */
    );
    filter: blur(6px);
    transform: translate(var(--J7p, 10%), -50%);
    border-radius: 100%;
    transition: 0.3s ease-in-out;
}

.container-botao::before,
.container-botao::after {
    content: "";
    position: absolute;
    top: 50%;
    left: 50%;
    width: 102%;
    height: 95%;
    transition: 0.3s ease-out;
    filter: blur(8px);
    background: linear-gradient(to right, transparent 0%, rgba(0, 255, 0, 0.3) 46.45%, #00cc00 90%, #00fe00);
    border-radius: 100px;
    transform: translate(-50%, -50%);
    z-index: 1;
    opacity: var(--R4h, 1);
}

.container-botao::after {
    background: linear-gradient(to left, transparent 0%, rgba(0, 255, 0, 0.2) 46.45%, #00cc00 90%, #00fe00);
    opacity: var(--K9y, 0);
}

.botao .elementor-button-text,
.botao .elementor-button-icon {
    position: relative;
    z-index: 3;
    white-space: nowrap;
}

.botao .elementor-button.ativo::before {
    transition: transform 0.1s ease-out !important;
}

.container-html {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 100%;
    height: 100%;
    background: none !important;
    mix-blend-mode: plus-lighter;
}

.glow::before,
.glow::after {
    content: "";
    position: absolute;
    top: 50%;
    left: 50%;
    width: 100%;
    height: 50%;
    transition: 0.3s ease-out;
    filter: blur(16px);
    background: linear-gradient(to right, transparent 0%, rgba(0, 255, 0, 0.2) 0%, #00cc00 80%, #00fe00);
    border-radius: 100px;
    transform: translate(-50%, -50%);
    z-index: 2;
    opacity: var(--R4h, 1);
}

.glow::before {
    background: linear-gradient(to left, transparent 0%, rgba(0, 255, 0, 0.2) 50%, #00cc00 80%, #00fe00);
    opacity: var(--K9y, 0);
}

.scroll-left{
    opacity: 0;
    transition: 0.5s all;
    transform: translate3d(-30px, 0, 0);
}

.scroll-right{
    opacity: 0;
    transition: 0.5s all;
    transform: translate3d(30px, 0, 0);
}

.scroll-bottom{
    opacity: 0;
    transition: 0.5s all;
    transform: translate3d(0, 80px, 0);
}

.scroll-top{
    opacity: 0;
    transition: 0.5s all;
    transform: translate3d(0, -80px, 0);
}

.ativo{
		opacity: 1;
    transition: 0.5s all;
    transform: translate3d(0, 0, 0);
}

