@property --x {
  syntax: '<percentage>';
  inherits: false;
  initial-value: 0%;
}

selector {
  background: radial-gradient(ellipse at var(--x) top, #FFFFFF25 0%, #000000 70%);
  animation: lightSweep 5s infinite alternate;
}

@keyframes lightSweep {
  0% {
    --x: 0%;
  }
  50% {
    --x: 50%;
  }
  100% {
    --x: 100%;
  }
}

